-- Reproducible schema for ATELIER 01.
create extension if not exists pgcrypto;
create table if not exists public.profiles (id uuid primary key references auth.users(id) on delete cascade,full_name text,avatar_url text,phone text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.categories (id uuid primary key default gen_random_uuid(),name text not null unique,slug text not null unique,description text,image_url text,created_at timestamptz not null default now());
create table if not exists public.products (id uuid primary key default gen_random_uuid(),category_id uuid references public.categories(id) on delete set null,name text not null,slug text not null unique,description text not null default '',price numeric(10,2) not null check(price>=0),compare_at_price numeric(10,2),image_url text,gallery text[] not null default '{}',sizes text[] not null default '{}',colors text[] not null default '{}',stock integer not null default 0 check(stock>=0),featured boolean not null default false,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.wishlist_items (user_id uuid references auth.users(id) on delete cascade,product_id uuid references public.products(id) on delete cascade,created_at timestamptz not null default now(),primary key(user_id,product_id));
create table if not exists public.cart_items (id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,product_id uuid not null references public.products(id) on delete cascade,quantity integer not null default 1 check(quantity>0),size text,color text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(user_id,product_id,size,color));
create table if not exists public.orders (id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,status text not null default 'pending' check(status in ('pending','confirmed','processing','shipped','delivered','cancelled')),subtotal numeric(10,2) not null check(subtotal>=0),shipping numeric(10,2) not null default 0 check(shipping>=0),total numeric(10,2) not null check(total>=0),shipping_address jsonb not null default '{}'::jsonb,payment_status text not null default 'demo_pending' check(payment_status in ('demo_pending','demo_paid','failed','refunded')),created_at timestamptz not null default now());
create table if not exists public.order_items (id uuid primary key default gen_random_uuid(),order_id uuid not null references public.orders(id) on delete cascade,product_id uuid references public.products(id) on delete set null,product_name text not null,unit_price numeric(10,2) not null,quantity integer not null check(quantity>0),size text,color text);
alter table public.profiles enable row level security; alter table public.categories enable row level security; alter table public.products enable row level security; alter table public.wishlist_items enable row level security; alter table public.cart_items enable row level security; alter table public.orders enable row level security; alter table public.order_items enable row level security;
revoke all on public.categories,public.products,public.profiles,public.wishlist_items,public.cart_items,public.orders,public.order_items from anon,authenticated;
grant select on public.categories,public.products to anon,authenticated; grant select,insert,update on public.profiles to authenticated; grant select,insert,delete on public.wishlist_items to authenticated; grant select,insert,update,delete on public.cart_items to authenticated; grant select,insert on public.orders,public.order_items to authenticated;
create policy "categories_public_select" on public.categories for select to anon,authenticated using (true); create policy "products_public_select" on public.products for select to anon,authenticated using (true);
create policy "profiles_owner_select" on public.profiles for select to authenticated using ((select auth.uid())=id); create policy "profiles_owner_insert" on public.profiles for insert to authenticated with check ((select auth.uid())=id); create policy "profiles_owner_update" on public.profiles for update to authenticated using ((select auth.uid())=id) with check ((select auth.uid())=id);
create policy "wishlist_owner_select" on public.wishlist_items for select to authenticated using ((select auth.uid())=user_id); create policy "wishlist_owner_insert" on public.wishlist_items for insert to authenticated with check ((select auth.uid())=user_id); create policy "wishlist_owner_delete" on public.wishlist_items for delete to authenticated using ((select auth.uid())=user_id);
create policy "cart_owner_select" on public.cart_items for select to authenticated using ((select auth.uid())=user_id); create policy "cart_owner_insert" on public.cart_items for insert to authenticated with check ((select auth.uid())=user_id); create policy "cart_owner_update" on public.cart_items for update to authenticated using ((select auth.uid())=user_id) with check ((select auth.uid())=user_id); create policy "cart_owner_delete" on public.cart_items for delete to authenticated using ((select auth.uid())=user_id);
create policy "orders_owner_select" on public.orders for select to authenticated using ((select auth.uid())=user_id); create policy "orders_owner_insert" on public.orders for insert to authenticated with check ((select auth.uid())=user_id); create policy "order_items_owner_select" on public.order_items for select to authenticated using (exists(select 1 from public.orders o where o.id=order_id and o.user_id=(select auth.uid()))); create policy "order_items_owner_insert" on public.order_items for insert to authenticated with check (exists(select 1 from public.orders o where o.id=order_id and o.user_id=(select auth.uid())));
create index if not exists products_category_id_idx on public.products(category_id); create index if not exists cart_items_user_id_idx on public.cart_items(user_id); create index if not exists cart_items_product_id_idx on public.cart_items(product_id); create index if not exists wishlist_items_user_id_idx on public.wishlist_items(user_id); create index if not exists wishlist_items_product_id_idx on public.wishlist_items(product_id); create index if not exists orders_user_id_idx on public.orders(user_id); create index if not exists order_items_order_id_idx on public.order_items(order_id); create index if not exists order_items_product_id_idx on public.order_items(product_id);
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$ begin insert into public.profiles(id,full_name) values(new.id,coalesce(new.raw_user_meta_data->>'full_name','')) on conflict(id) do nothing; return new; end; $$; revoke execute on function public.handle_new_user() from public,anon,authenticated; drop trigger if exists on_auth_user_created on auth.users; create trigger on_auth_user_created after insert on auth.users for each row execute function public.handle_new_user();
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values ('avatars','avatars',true,2097152,array['image/jpeg','image/png','image/webp']),('product-media','product-media',true,5242880,array['image/jpeg','image/png','image/webp']) on conflict(id) do update set public=excluded.public,file_size_limit=excluded.file_size_limit,allowed_mime_types=excluded.allowed_mime_types;
create policy "avatar_public_read" on storage.objects for select to anon,authenticated using(bucket_id='avatars'); create policy "avatar_owner_insert" on storage.objects for insert to authenticated with check(bucket_id='avatars' and (storage.foldername(name))[1]=(select auth.uid())::text); create policy "avatar_owner_update" on storage.objects for update to authenticated using(bucket_id='avatars' and owner_id=(select auth.uid())::text) with check(bucket_id='avatars' and (storage.foldername(name))[1]=(select auth.uid())::text); create policy "avatar_owner_delete" on storage.objects for delete to authenticated using(bucket_id='avatars' and owner_id=(select auth.uid())::text); create policy "product_media_public_read" on storage.objects for select to anon,authenticated using(bucket_id='product-media');
